-- November28 pet-service discovery and4exact event additions. Data only.
begin;
do $correct$ declare bid uuid:='04cd7731-a334-4e5f-828f-570b7f5fd9a1'; ob jsonb; oc jsonb; nb jsonb; nc jsonb; begin
select to_jsonb(b) into ob from businesses b where id=bid and name='iThink Pet' and website='https://www.ithinkpet.com/' and status='approved' for update;
select to_jsonb(c) into oc from listing_checks c where business_id=bid and service_areas=array['Mountain House','Tracy','Lathrop','Manteca'] and service_tags=array['pet sitting','dog walking','cat sitting'] for update;
if ob is null or oc is null then raise exception 'iThink record changed; inspect first';end if;
update businesses set description='Advertises pet sitting, neighborhood dog walking, cat sitting and pet boarding on its Central Valley page, which explicitly names Mountain House, Tracy, Lathrop and Manteca. Travel and holiday charges may apply. Confirm your address, pet needs, full quote and dates directly. For boarding, confirm the care location, pet eligibility and pickup/drop-off arrangements before booking; no visitor office or available space established.' where id=bid;
update listing_checks set source_url='https://www.ithinkpet.com/central-valley-rates.html',checked_at=now(),service_tags=array['pet sitting','dog walking','cat sitting','pet boarding'],checked_fields=array['identity','public text number','website','advertised services','explicit service cities','boarding arrangements limitations'],scope_note='Fresh first-party Central Valley rates HTTP200/web check November28,2026: all4named cities, text5102741750, sitting,30minute neighborhood walks, cat care and advertised boarding. Added boarding discovery tag to existing business; original approval/city scope retained. Boarding care location, animal acceptance, transport arrangements and available spaces not established; confirm directly. No price guarantee, holiday availability, credentials/insurance/quality/medical capability confirmed. Site photo-sharing prohibition respected; no photos copied.' where business_id=bid;
select to_jsonb(b) into nb from businesses b where id=bid;select to_jsonb(c) into nc from listing_checks c where business_id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference)values(bid,ob||jsonb_build_object('listing_check',oc),nb||jsonb_build_object('listing_check',nc),'Add explicitly advertised boarding service discovery to existing four-city pet provider; no new provider or coverage expansion','https://www.ithinkpet.com/central-valley-rates.html');
end $correct$;
